// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        vm.assume(firstVal != secondVal);

        c.SetMinSum(firstVal);
        c.Initialized();

        bool ok = true;
        try c.SetMinSum(secondVal) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "SetMinSum should revert after initialization");
    }
}
